// Simple hash function
function createId(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return hash.toString();
}

const news = items[0].json.news_results || [];

return news.map(n => {
  const title = (n.title || "").trim();
  const description = (n.snippet || "").trim();

  const combined_text = `${title}. ${description}`.toLowerCase();

  const id = createId(title + description);

  return {
    json: {
      id,
      title,
      description,
      source: n.source || "unknown",
      url: n.link || "",
      publishedAt: n.date || new Date().toISOString(),
      combined_text
    }
  };
});

const existing = $items("Fetch Existing News").map(i => i.json.id);

return items.filter(item => {
  return !existing.includes(item.json.id);
});

const rules = $items("Fetch Macro Rules") || [];

return items.map(item => {
  const text = (item.json.combined_text || "").toLowerCase();

  let matches = [];
  let score = 0;
  let seen = new Set();

  for (const r of rules) {
    const keyword = (r.json.Keyword || "")
      .toLowerCase()
      .trim();

    if (keyword && text.includes(keyword) && !seen.has(keyword)) {
      seen.add(keyword);

      matches.push({
        keyword: r.json.Keyword,
        impact: r.json.Impact,
        asset: r.json.Asset,
        sentiment: r.json.Sentiment,
        weight: r.json.Weight
      });

      score += Number(r.json.Weight || 0);
    }
  }

  return {
    json: {
      ...item.json,
      rule_matches: matches,
      rule_score: score
    }
  };
});

