return items.map(item => {
  const ai = item.json.output || {};

  return {
    json: {
      ...item.json,
      ...ai
    }
  };
});

return items.map(item => {
  const ruleScore = Number(item.json.rule_score || 0);
  const confidence = Number(item.json.confidence || 0);

  let impactBoost = 0;

  // Boost based on impact level
  if (item.json.impact_level === "high") impactBoost = 20;
  else if (item.json.impact_level === "medium") impactBoost = 10;

  // Final score calculation
  const final_score = ruleScore + confidence + impactBoost;

  return {
    json: {
      ...item.json,
      final_score
    }
  };
});

return items.map(item => {
  const score = Number(item.json.final_score || 0);

  let impact_level_final = "low";

  if (score >= 90) impact_level_final = "high";
  else if (score >= 60) impact_level_final = "medium";

  return {
    json: {
      ...item.json,
      impact_level_final
    }
  };
});
